// Extract query parameters
const body = $input.item.json.body;
const currentLat = body.current_lat;
const currentLng = body.current_lng;
const destinationLat = body.destination_lat;
const destinationLng = body.destination_lng;
const destinationName = body.destination_name || 'Destination';
const placeType = body.place_type || 'atm';
const keyword = body.keyword || null;
const maxDetourMinutes = body.max_detour_minutes || 2;

return {
  json: {
    current_lat: currentLat,
    current_lng: currentLng,
    destination_lat: destinationLat,
    destination_lng: destinationLng,
    destination_name: destinationName,
    place_type: placeType,
    keyword: keyword,
    max_detour_minutes: maxDetourMinutes
  }
};

// Decode polyline and sample route points
function decodePolyline(encoded) {
  const poly = [];
  let index = 0;
  const len = encoded.length;
  let lat = 0;
  let lng = 0;

  while (index < len) {
    let b;
    let shift = 0;
    let result = 0;
    do {
      b = encoded.charCodeAt(index++) - 63;
      result |= (b & 0x1f) << shift;
      shift += 5;
    } while (b >= 0x20);
    const dlat = ((result & 1) ? ~(result >> 1) : (result >> 1));
    lat += dlat;

    shift = 0;
    result = 0;
    do {
      b = encoded.charCodeAt(index++) - 63;
      result |= (b & 0x1f) << shift;
      shift += 5;
    } while (b >= 0x20);
    const dlng = ((result & 1) ? ~(result >> 1) : (result >> 1));
    lng += dlng;

    poly.push({ lat: lat / 1E5, lng: lng / 1E5 });
  }

  return poly;
}

function samplePoints(points, intervalMeters) {
  if (points.length === 0) return [];

  const sampled = [points[0]];
  let accumulatedDistance = 0;

  for (let i = 1; i < points.length; i++) {
    const distance = calculateDistance(points[i - 1], points[i]);
    accumulatedDistance += distance;

    if (accumulatedDistance >= intervalMeters) {
      sampled.push(points[i]);
      accumulatedDistance = 0;
    }
  }

  return sampled;
}

function calculateDistance(p1, p2) {
  const R = 6371000;
  const dLat = (p2.lat - p1.lat) * Math.PI / 180;
  const dLng = (p2.lng - p1.lng) * Math.PI / 180;

  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(p1.lat * Math.PI / 180) * Math.cos(p2.lat * Math.PI / 180) *
            Math.sin(dLng / 2) * Math.sin(dLng / 2);

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return R * c;
}

const routeData = $input.item.json;
const polyline = routeData.routes[0].overview_polyline.points;
const routePoints = decodePolyline(polyline);
const sampledPoints = samplePoints(routePoints, 2000); // Sample every 2km

return sampledPoints.map(point => ({
  json: {
    lat: point.lat,
    lng: point.lng,
    place_type: $('Parse Query').item.json.place_type,
    keyword: $('Parse Query').item.json.keyword
  }
}));

// Aggregate and deduplicate places
const allPlaces = [];
const seenPlaces = new Set();

for (const item of $input.all()) {
  if (item.json.results) {
    for (const place of item.json.results) {
      const key = `${place.geometry.location.lat},${place.geometry.location.lng}`;
      if (!seenPlaces.has(key)) {
        seenPlaces.add(key);
        allPlaces.push({
          name: place.name,
          address: place.vicinity || '',
          lat: place.geometry.location.lat,
          lng: place.geometry.location.lng,
          rating: place.rating || 0,
          is_open: place.opening_hours?.open_now
        });
      }
    }
  }
}

return allPlaces.map(place => ({ json: place }));

